  return {
    status,
    contentType: "application/json",
    body: JSON.stringify(body),
  };
}

function transaction(
  transactionId: string,
  status: string,
  extra: Record<string, unknown> = {},
) {
  return {
    id: faker.string.uuid(),
    transaction_id: transactionId,
    adapter: "bap",
    flow: "referral",
    status,
    network_id: "nfh",
    counterparty_id: "cc.bpp",
